css:
/* Маркер под фразой. Цвет — accent, смешанный с фоном блока: заливка НЕпрозрачная, поэтому на стыках слов нет швов.
   Текст поверх маркера обязан держать контраст ≥ 4.5:1 — на тёмной теме уменьшите долю accent до 30–40 %.
   Блок на карточке, а не на фоне страницы: --mh-bg = цвет карточки (surface). */
.mh {
  --mh-bg: var(--background, #ffffff);
  --mh-color: color-mix(in srgb, var(--accent, #ffd23f) 65%, var(--mh-bg));
  --mh-top: 34%;          /* верх маркера от верха строчных букв: 0% — во всю высоту шрифта, 34% — от середины букв, как фломастером */
  --mh-bottom: 8%;        /* низ маркера: чуть ниже линии букв */
  color: inherit;
  /* Без JS, в печати и при уменьшении движения — то же выделение статичным фоном, на всех строках */
  background: linear-gradient(transparent var(--mh-top), var(--mh-color) var(--mh-top), var(--mh-color) calc(100% - var(--mh-bottom)), transparent calc(100% - var(--mh-bottom)));
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
/* JS разбил фразу на слова: фон переходит на маркер каждого слова (псевдоэлемент, анимируется только transform) */
.mh.mh--split { background: none; }
.mh__w { position: relative; z-index: 0; }   /* слово — свой слой: маркер ложится ПОД буквы */
.mh__w::before {
  content: "";
  position: absolute;
  z-index: -1;
  left: 0; right: -1px;                      /* 1px внахлёст на соседа: заливка непрозрачная, шва нет */
  top: var(--mh-top); bottom: var(--mh-bottom);
  background: var(--mh-color);
  transform-origin: 0 50%;                   /* слева направо; для rtl — 100% 50% */
}
.mh__w:first-child::before { left: -.08em; border-radius: .16em 0 0 .16em; }
.mh__w:last-child::before { right: -.08em; border-radius: 0 .16em .16em 0; }
.mh__w:only-child::before { border-radius: .16em; }
@media (prefers-reduced-motion: no-preference) {
  .mh-on .mh:not(.mh--split) { background: none; }  /* ждём скрипт: статичный фон не мигает перед проездом */
  .mh[data-mh="wait"] .mh__w::before { transform: scaleX(0); }
  .mh[data-mh="run"] .mh__w::before {
    transition: transform var(--d, 150ms) linear var(--t, 0ms); /* ровная скорость по всем словам, вся фраза 450ms */
  }
}
/* Уменьшение движения (уровень «убрать»): выделение стоит сразу, маркер не едет */
@media (prefers-reduced-motion: reduce) {
  .mh__w::before { transform: none !important; transition: none !important; }
}
@media print {
  .mh__w::before { transform: none !important; }
}
/* Контрастная тема Windows: системный цвет выделения, иначе заливку подменит фон и маркер исчезнет */
@media (forced-colors: active) {
  .mh { forced-color-adjust: none; background: Mark; color: MarkText; }
  .mh.mh--split { background: none; }
  .mh__w::before { forced-color-adjust: none; background: Mark; top: 0; bottom: 0; }
}

js:
// Маркер под фразой: без зависимостей. Фраза делится на слова, маркер проезжает их с одной скоростью.
(() => {
  window.__mh = true; // сигнал строчке в <head>: скрипт жив
  const els = document.querySelectorAll('[data-mh]');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  if (!els.length || reduce.matches || !('IntersectionObserver' in window)) { // выделение стоит статичным фоном
    document.documentElement.classList.remove('mh-on');
    return;
  }
  const T = 450; // вся фраза, мс (300–500)
  const io = new IntersectionObserver((es) => es.forEach((e) => {
    if (!e.isIntersecting) return;
    io.unobserve(e.target); // один раз, без повтора при прокрутке назад
    const el = e.target;
    setTimeout(() => { el.dataset.mh = 'run'; }, parseFloat(el.dataset.mhDelay) || 0);
  }), { threshold: 1, rootMargin: '0px 0px -15% 0px' });
  els.forEach((el) => {
    if (el.children.length) return; // внутри теги — не трогаем, остаётся статичное выделение
    // только обычные пробелы: &nbsp; остаётся внутри слова, «500 ₽» не разорвётся
    const words = el.textContent.trim().split(/[ \t\r\n]+/);
    el.textContent = '';
    const ws = words.map((w, i) => {
      const s = document.createElement('span'); s.className = 'mh__w';
      s.textContent = i < words.length - 1 ? w + ' ' : w; // пробел внутри слова: маркер идёт без разрывов
      return el.appendChild(s);
    });
    const widths = ws.map((w) => w.getBoundingClientRect().width); // одно чтение раскладки на фразу
    const sum = widths.reduce((a, b) => a + b, 0) || 1;
    let t = 0;
    ws.forEach((w, i) => { // время слова пропорционально его ширине — скорость маркера ровная
      const d = (T * widths[i]) / sum;
      w.style.setProperty('--t', Math.round(t) + 'ms');
      w.style.setProperty('--d', Math.round(d) + 'ms');
      t += d;
    });
    el.classList.add('mh--split'); el.dataset.mh = 'wait';
    if (!el.hasAttribute('data-mh-manual')) io.observe(el); // data-mh-manual: запуск из своей шкалы (el.dataset.mh = 'run'), страховка 4 с
    else setTimeout(() => { if (el.dataset.mh === 'wait') el.dataset.mh = 'run'; }, 4000);
  });
})();

gsap_alt:
// GSAP здесь не нужен: маркер — CSS-переход псевдоэлемента, GSAP его напрямую не двигает.
// Если на первом экране уже есть временная шкала GSAP (npm i gsap, без CDN), запускайте проезд маркера из неё,
// чтобы он шёл после заголовка: JS рецепта оставьте (он делит фразу на слова), у <mark> поставьте data-mh-manual
// (скрипт рецепта тогда не запускает проезд сам и ждёт команды; если её нет 4 с — запускает сам), data-mh-delay не нужен.
import { gsap } from 'gsap';

const mark = document.querySelector('.hero [data-mh]');
const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', reduce: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  if (conditions.reduce || !mark) return; // при reduce выделение стоит статично — делать нечего
  const tl = gsap.timeline();
  tl.from('.hero h1', { opacity: 0, y: 24, duration: 0.6, ease: 'power3.out' })
    .call(() => { if (mark.dataset.mh === 'wait') mark.dataset.mh = 'run'; }, null, '-=0.15'); // маркер — сразу после заголовка
  return () => tl.revert();
});
